def find_path(graph, start, goal):
    stack = [(set(), start)]
    visited = set()

    while stack:
        (visited_asc, current) = stack[-1]
        if current == goal:
            return visited_asc.union({current})
        stack.pop()
        if current not in visited:
            visited.add(current)
            for neighbor in graph.get(current, ()):
                if neighbor not in visited_asc:
                    stack.append((visited_asc.union({current}), neighbor))
    return None

