def find_path(graph, start, goal):
    visited = set()  # Set to keep track of visited nodes
    path_stack = []  # Stack for path elements
    path_stack.append(start)  # Start node

    while path_stack:
        current = path_stack[-1]
        if current == goal:
            return path_stack  # Found a path
        if current not in visited:
            visited.add(current)
            neighbors = graph.get(current, [])
            for neighbor in neighbors:
                if neighbor not in visited:
                    path_stack.append(neighbor)
                    break
            else:  # Else part is executed if the loop is exhausted (no break)
                path_stack.pop()  # Remove the last node from the stack

    return None  # No path found from start to goal
